from pathlib import Path
from html import escape
root = Path(__file__).resolve().parent

NAVS=[('index.html','Home'),('services.html','Services'),('order.html','Get a Quote'),('process.html','How It Works'),('about.html','About')]

def shell(file,title,description,body,script=False):
    nav=''.join(f'<a href="{url}" {"aria-current=\"page\"" if file==url else ""} class="{ "nav-cta" if url=="order.html" else ""}">{label}</a>' for url,label in NAVS)
    pyhead='''<link rel="stylesheet" href="https://pyscript.net/releases/2026.7.3/core.css" />
<script type="module" src="https://pyscript.net/releases/2026.7.3/core.js"></script>''' if script else ''
    pybody='''<script type="py" src="./py/order.py" config='{"files":{"./py/pricing.py":"./pricing.py"}}'></script>''' if script else ''
    return f'''<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="description" content="{escape(description)}"><title>{escape(title)} | PrintConnect</title>
<link rel="icon" type="image/svg+xml" href="assets/logo.svg"><link rel="stylesheet" href="assets/styles.css">
{pyhead}<script src="assets/site.js" defer></script></head>
<body><header class="site-header"><div class="container nav-row"><a class="brand" href="index.html" aria-label="PrintConnect home"><img src="assets/logo.svg" alt=""><span>Print<span>Connect.</span></span></a>
<button class="menu-button" id="menu-button" aria-controls="nav-links" aria-expanded="false" aria-label="Toggle menu">☰ Menu</button>
<nav class="nav-links" id="nav-links" aria-label="Main navigation">{nav}</nav></div></header>
<main>{body}</main>
<footer class="footer"><div class="container"><div class="footer-top"><div><a class="brand" href="index.html"><img src="assets/logo.svg" alt=""><span>Print<span>Connect.</span></span></a><p style="max-width:285px;margin-top:14px">A student-centered on-campus printing concept created for Cebu Eastern College.</p></div>
<div><strong>Explore the site</strong><div class="footer-links"><a href="services.html">Printing services</a><a href="order.html">Instant price quote</a><a href="process.html">How printing works</a><a href="about.html">Our founders</a></div></div>
<div><strong>Academic project</strong><p style="margin-top:15px">Event-Driven Programming<br>Cebu Eastern College, Inc.<br>Made by Zianne B. Pontanar and Daniel D. Pacundo</p></div></div>
<div class="footer-bottom"><span>© 2026 PrintConnect. Academic website prototype.</span><span>Prices are planning estimates • No actual orders are transmitted</span></div></div></footer>
{pybody}</body></html>'''

def save(name,title,desc,body,script=False):
    (root/name).write_text(shell(name,title,desc,body,script),encoding='utf8')

